  font-display: swap;
}

:root {
  --bg: #07090a;
  --bg-2: #0b0f10;
  --ink: #eeeee6;
  --ink-soft: #c9ccc4;
  --dim: #84918d;
  --dim-2: #596562;
  --line: rgba(200, 218, 211, 0.17);
  --line-strong: rgba(218, 234, 227, 0.34);
  --orange: #ff8b38;
  --orange-2: #ffc177;
  --orange-deep: #c65218;
  --teal: #8ee6d0;
  --red: #ff493e;
  --green: #9ee08f;
  --panel: rgba(8, 12, 12, 0.72);
  --display: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --mono: 'JetBrains Mono', 'Courier New', monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  touch-action: none;
  user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
}

.hidden {
  display: none !important;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #07090a;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

/* ---------- global overlay effects ---------- */
.screen-fx {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}

.fx-vignette {
  position: absolute;
  inset: -1px;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(0, 0, 0, 0.22) 72%, rgba(0, 0, 0, 0.68) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.28), transparent 16%, transparent 82%, rgba(0, 0, 0, 0.38));
}

.fx-grain {
  position: absolute;
  inset: -30%;
  opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.75'/%3E%3C/svg%3E");
  animation: grainShift 0.22s steps(2) infinite;
  mix-blend-mode: overlay;
}

@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

.fx-scanlines {
  position: absolute;
  inset: 0;
  opacity: 0.12;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 2px, rgba(0, 0, 0, 0.22) 3px, transparent 4px);
  mix-blend-mode: multiply;
}

#damage-flash {
  position: absolute;
  inset: 0;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 25%, rgba(177, 13, 8, 0.24) 62%, rgba(104, 6, 3, 0.82) 100%),
    linear-gradient(90deg, rgba(255, 58, 41, 0.2), transparent 20%, transparent 80%, rgba(255, 58, 41, 0.2));
  transition: opacity 0.12s linear;
}

#low-health {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 36%, rgba(111, 3, 0, 0.5) 100%);
  animation: lowHealthPulse 1.3s ease-in-out infinite;
  transition: opacity 0.5s ease;
}

@keyframes lowHealthPulse {
  0%, 100% { filter: brightness(0.8); }
  50% { filter: brightness(1.5); }
}

/* ---------- boot ---------- */
.boot {
  position: absolute;
  inset: 0;
  z-index: 300;
  background:
    radial-gradient(circle at 50% 42%, rgba(255, 137, 55, 0.055), transparent 32%),
    #060809;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: opacity 0.6s ease, visibility 0.6s;
}

.boot.done {
  opacity: 0;
  visibility: hidden;
}

.boot-mark {
  width: 52px;
  height: 46px;
  display: flex;
  gap: 5px;
  align-items: flex-end;
  margin-bottom: 24px;
}

.boot-mark span {
  display: block;
  width: 9px;
  background: var(--orange);
  animation: bootBars 1s ease-in-out infinite alternate;
  box-shadow: 0 0 20px rgba(255, 139, 56, 0.35);
}

.boot-mark span:nth-child(1) { height: 20px; animation-delay: 0s; }
.boot-mark span:nth-child(2) { height: 42px; animation-delay: 0.12s; }
.boot-mark span:nth-child(3) { height: 31px; animation-delay: 0.24s; }

@keyframes bootBars {
  to { height: 12px; opacity: 0.4; }
}

.boot-brand {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.38em;
  color: var(--ink-soft);
}

.boot-brand b {
  color: var(--orange);
  font-weight: 400;
}

.boot-bar {
  width: min(340px, 60vw);
  height: 1px;
  background: rgba(255, 255, 255, 0.12);
  margin-top: 28px;
  overflow: hidden;
}

.boot-bar i {
  display: block;
  width: 0%;
  height: 100%;
  background: var(--orange);
  box-shadow: 0 0 9px var(--orange);
  transition: width 0.25s ease;
}

.boot-log {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--dim);
  margin-top: 14px;
  height: 14px;
}

.boot-corner {
  position: absolute;
  bottom: 28px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--dim-2);
}

/* ---------- main menu ---------- */
.menu {
  position: absolute;
  inset: 0;
  z-index: 100;
  overflow-y: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  background:
    linear-gradient(90deg, rgba(5, 7, 8, 0.97) 0%, rgba(5, 7, 8, 0.9) 30%, rgba(5, 7, 8, 0.44) 62%, rgba(5, 7, 8, 0.14) 100%),
    linear-gradient(180deg, rgba(5, 7, 8, 0.66), transparent 20%, transparent 74%, rgba(5, 7, 8, 0.9));
}

.menu::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent 0, transparent calc(50% - 0.5px), rgba(200, 220, 212, 0.045) calc(50% - 0.5px), rgba(200, 220, 212, 0.045) calc(50% + 0.5px), transparent calc(50% + 0.5px)),
    radial-gradient(circle at 66% 48%, transparent 0, transparent 22%, rgba(0, 0, 0, 0.22) 58%, rgba(0, 0, 0, 0.5) 100%);
}

.menu-shade {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(115deg, transparent 62%, rgba(255, 139, 56, 0.035) 62.2%, transparent 62.4%);
}

.menu-top {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: max(26px, env(safe-area-inset-top)) clamp(24px, 4vw, 64px) 0;
  flex: 0 0 auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
}

.brand-glyph {
  width: 37px;
  height: 37px;
  color: var(--orange);
  filter: drop-shadow(0 0 14px rgba(255, 139, 56, 0.28));
}

.brand-glyph svg {
  width: 100%;
  height: 100%;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.3;
}

.brand-glyph svg path:nth-child(2) {
  opacity: 0.55;
}

.brand-glyph svg path:nth-child(3) {
  fill: currentColor;
  stroke: none;
}

.brand-name {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.32em;
  line-height: 1;
}

.brand-sub {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.22em;
  color: var(--dim);
  margin-top: 6px;
}

.menu-status {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-top: 3px;
  text-align: right;
}

.menu-status > div {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.menu-status b {
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 400;
  letter-spacing: 0.18em;
  color: var(--ink-soft);
}

.menu-status small {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--dim-2);
}

.status-dot {
  width: 5px;
  height: 5px;
  background: var(--green);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--green);
  animation: statusBlink 2.4s ease-in-out infinite;
}

@keyframes statusBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.25; }
}

.menu-clock {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--dim);
  border-left: 1px solid var(--line);
  padding-left: 14px;
  margin-left: 3px;
}

.menu-content {
  position: relative;
  z-index: 2;
  flex: 1 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(290px, 0.48fr);
  align-items: center;
  gap: clamp(26px, 4vw, 80px);
  width: min(1560px, 100%);
  margin: 0 auto;
  padding: 32px clamp(24px, 4vw, 64px) 34px;
}

.menu-hero {
  min-width: 0;
  animation: menuIn 0.9s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes menuIn {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--dim);
  margin-bottom: 13px;
}

.eyebrow i {
  width: 17px;
  height: 1px;
  background: var(--orange);
}

.eyebrow span {
  color: var(--orange);
}

.title {
  margin: 0;
  display: flex;
  flex-direction: column;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 0.76;
  text-transform: uppercase;
}

.title-solid {
  font-size: clamp(72px, 10.4vw, 170px);
  color: var(--ink);
  text-shadow: 0 5px 40px rgba(0, 0, 0, 0.55);
}

.title-ghost {
  font-size: clamp(55px, 8.1vw, 132px);
  color: transparent;
  -webkit-text-stroke: 1px rgba(239, 240, 232, 0.5);
  text-stroke: 1px rgba(239, 240, 232, 0.5);
  letter-spacing: 0.025em;
  transform: translateX(2px);
  position: relative;
}

.title-ghost::after {
  content: '';
  position: absolute;
  left: 1%;
  right: 38%;
  bottom: -17px;
  height: 2px;
  background: linear-gradient(90deg, var(--orange), rgba(255, 139, 56, 0));
}

.hero-copy {
  width: min(520px, 88%);
  margin: 30px 0 24px;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.85;
  color: #a9b0aa;
  letter-spacing: 0.02em;
}

.mission-card {
  width: min(610px, 100%);
  border: 1px solid var(--line);
  background: linear-gradient(135deg, rgba(15, 20, 20, 0.82), rgba(8, 11, 12, 0.6));
  backdrop-filter: blur(10px);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.3);
  clip-path: polygon(0 0, calc(100% - 17px) 0, 100% 17px, 100% 100%, 0 100%);
}

.mission-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.mission-head > div:first-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.mission-head span {
