  inset: 0;
  background:
    linear-gradient(115deg, transparent 48%, rgba(120, 220, 188, 0.06) 49%, transparent 50%),
    linear-gradient(65deg, transparent 48%, rgba(120, 220, 188, 0.045) 49%, transparent 50%);
}

.map-zone {
  position: absolute;
