}

.map-radar {
  position: absolute;
  width: 88px;
  height: 88px;
  border: 1px solid rgba(126, 214, 185, 0.2);
  border-radius: 50%;
  left: 47%;
  top: 41%;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 30px rgba(71, 168, 139, 0.08) inset;
}

.map-radar::before,
.map-radar::after {
  content: '';
