}

.map-radar::before {
  width: 1px;
  height: 100%;
  left: 50%;
}

.map-radar::after {
  height: 1px;
  width: 100%;
  top: 50%;
}

.map-sweep {
  position: absolute;
  width: 88px;
  height: 88px;
  left: 47%;
  top: 41%;
  transform: translate(-50%, -50%);
