}

.p1 { left: 25%; top: 22%; }
.p2 { left: 64%; top: 27%; color: var(--teal); border-color: var(--teal); }
.p3 { left: 72%; top: 66%; color: var(--teal); border-color: var(--teal); }

.map-footer {
  position: absolute;
  left: 7px;
  right: 7px;
  bottom: 6px;
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: var(--dim-2);
}

.intel-rows {
  display: flex;
  flex-direction: column;
  margin-top: 11px;
}

.intel-rows > div {
  display: flex;
  justify-content: space-between;
  padding: 7px 0;
  border-bottom: 1px solid rgba(200, 218, 211, 0.075);
}

.intel-rows span {
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.14em;
  color: var(--dim-2);
}

.intel-rows b {
  font-family: var(--mono);
  font-size: 6.5px;
  font-weight: 400;
  letter-spacing: 0.1em;
