  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--dim-2);
  flex: 0 0 auto;
}

.footer-center {
  opacity: 0.65;
}

.mobile-tip {
  display: none;
  position: relative;
  z-index: 2;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  color: var(--orange);
  padding: 0 24px 14px;
}

/* ---------- HUD ---------- */
.hud {
  position: absolute;
  inset: 0;
  z-index: 50;
  pointer-events: none;
  font-family: var(--display);
}

.compass-wrap {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  left: 50%;
  width: min(700px, 70vw);
  transform: translateX(-50%);
  opacity: 0.82;
  animation: hudFadeIn 0.8s ease both;
}

.compass-wrap canvas {
  display: block;
  width: 100%;
  height: 25px;
}

.compass-notch {
  position: absolute;
  left: 50%;
  top: -3px;
  width: 1px;
  height: 8px;
  background: var(--orange);
  box-shadow: 0 0 9px var(--orange);
}

.compass-degree {
  position: absolute;
  top: 23px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--orange);
}

@keyframes hudFadeIn {
  from { opacity: 0; transform: translate(-50%, -6px); }
  to { opacity: 0.82; transform: translate(-50%, 0); }
}

.objective-panel {
  position: absolute;
  left: clamp(18px, 3vw, 44px);
  top: clamp(22px, 4vh, 42px);
  width: 324px;
  padding: 12px 14px 12px 16px;
  border-left: 2px solid var(--orange);
  background: linear-gradient(90deg, rgba(5, 9, 9, 0.72), rgba(5, 9, 9, 0.05) 92%, transparent);
  animation: hudSlideLeft 0.65s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes hudSlideLeft {
  from { opacity: 0; transform: translateX(-16px); }
  to { opacity: 1; transform: translateX(0); }
}

.obj-tag {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--orange);
}

.obj-tag i {
  display: block;
  width: 4px;
  height: 4px;
  background: var(--orange);
  animation: statusBlink 1.5s infinite;
}

.obj-title {
  margin-top: 4px;
  font-size: 25px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: 0.07em;
}

.obj-sub {
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: var(--dim);
}

.wave-line {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--ink-soft);
}

.wave-line span:last-child {
  color: var(--orange-2);
}

.wave-bar {
  height: 2px;
  background: rgba(255, 255, 255, 0.12);
  margin-top: 6px;
  overflow: hidden;
}

.wave-bar i {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--orange);
  box-shadow: 0 0 8px rgba(255, 139, 56, 0.55);
  transition: width 0.5s ease;
}

.radar-panel {
  position: absolute;
  right: clamp(18px, 3vw, 44px);
  top: clamp(22px, 4vh, 42px);
  width: 198px;
  padding: 10px;
  background: rgba(5, 9, 9, 0.62);
  border: 1px solid rgba(196, 218, 208, 0.14);
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 0 100%);
  animation: hudSlideRight 0.65s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes hudSlideRight {
  from { opacity: 0; transform: translateX(16px); }
  to { opacity: 1; transform: translateX(0); }
}

.radar-top,
.radar-bottom {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.12em;
  color: var(--dim);
}

.radar-top b {
  color: var(--ink-soft);
  font-weight: 400;
}

.radar-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  margin: 7px 0;
  border: 1px solid rgba(139, 200, 181, 0.2);
  background: radial-gradient(circle, rgba(31, 77, 66, 0.3), rgba(5, 10, 9, 0.78) 76%);
  overflow: hidden;
}

.radar-frame canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.radar-cross {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent calc(50% - 0.5px), rgba(147, 219, 196, 0.15) 50%, transparent calc(50% + 0.5px)),
    linear-gradient(transparent calc(50% - 0.5px), rgba(147, 219, 196, 0.15) 50%, transparent calc(50% + 0.5px));
}

.radar-sweep {
  position: absolute;
  inset: -1px;
  border-radius: 50%;
  background: conic-gradient(from 0deg, transparent 0 318deg, rgba(135, 232, 201, 0.22) 352deg, transparent 360deg);
  animation: radarSweep 3.6s linear infinite;
}

@keyframes radarSweep {
  to { transform: rotate(360deg); }
}

.radar-n {
  position: absolute;
  top: 3px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 5.5px;
  color: var(--orange);
}

.radar-bottom {
  color: var(--dim-2);
}

.radar-live {
  display: flex;
  gap: 4px;
  align-items: center;
  color: var(--green);
}

.radar-live i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 5px var(--green);
}

.score-panel {
  position: absolute;
  right: clamp(18px, 3vw, 44px);
  top: calc(clamp(22px, 4vh, 42px) + 252px);
  display: flex;
  gap: 16px;
  padding: 8px 10px;
  background: rgba(5, 9, 9, 0.44);
  border-top: 1px solid rgba(196, 218, 208, 0.12);
  font-family: var(--mono);
}

.score-panel > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.score-panel span {
  font-size: 5.5px;
  letter-spacing: 0.16em;
  color: var(--dim-2);
}

.score-panel b {
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0.05em;
  color: var(--ink-soft);
}

.score-panel > div:first-child b {
  color: var(--orange-2);
}

.killfeed {
  position: absolute;
  right: clamp(18px, 3vw, 44px);
  top: calc(clamp(22px, 4vh, 42px) + 296px);
  width: 290px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.killfeed-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--ink-soft);
  background: linear-gradient(90deg, transparent, rgba(5, 9, 9, 0.68));
  padding: 5px 7px 5px 18px;
  animation: killIn 0.22s ease both;
}

.killfeed-item b {
  color: var(--orange);
  font-weight: 400;
}

.killfeed-item .hs {
  color: var(--orange-2);
  font-size: 6px;
  border: 1px solid rgba(255, 177, 107, 0.4);
  padding: 1px 3px;
}

@keyframes killIn {
  from { opacity: 0; transform: translateX(12px); }
  to { opacity: 1; transform: translateX(0); }
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
  --ch-gap: 10px;
  transition: opacity 0.18s ease;
}

.ch {
  position: absolute;
  background: rgba(245, 247, 240, 0.9);
  box-shadow: 0 0 3px rgba(0, 0, 0, 0.8);
}

.ch-t,
.ch-b {
  width: 1px;
  height: 7px;
  left: 0;
}

.ch-l,
.ch-r {
  width: 7px;
  height: 1px;
  top: 0;
}

.ch-t { bottom: calc(var(--ch-gap) + 7px); }
.ch-b { top: calc(var(--ch-gap) + 7px); }
.ch-l { right: calc(var(--ch-gap) + 7px); }
.ch-r { left: calc(var(--ch-gap) + 7px); }

.ch-dot {
  position: absolute;
  width: 2px;
  height: 2px;
  left: -1px;
  top: -1px;
  background: rgba(255, 255, 255, 0.95);
  border-radius: 50%;
}

.crosshair.ads .ch {
  opacity: 0.25;
}

.crosshair.ads .ch-dot {
  opacity: 1;
  background: var(--orange);
  box-shadow: 0 0 6px var(--orange);
}

.crosshair.reloading {
  opacity: 0.22;
}

.hitmarker {
  position: absolute;
  left: 0;
  top: 0;
  opacity: 0;
  transform: translate(-50%, -50%) rotate(45deg) scale(0.8);
  transition: opacity 0.08s ease, transform 0.16s ease;
}

.hitmarker.show {
  opacity: 1;
  transform: translate(-50%, -50%) rotate(45deg) scale(1);
}

.hitmarker.headshot i {
  background: var(--orange);
  box-shadow: 0 0 6px var(--orange);
}

.hitmarker i {
  position: absolute;
  width: 9px;
  height: 1px;
  background: #fff;
}

.hitmarker i:nth-child(1) { left: -13px; top: -7px; transform: rotate(45deg); }
.hitmarker i:nth-child(2) { left: 4px; top: -7px; transform: rotate(-45deg); }
.hitmarker i:nth-child(3) { left: -13px; top: 7px; transform: rotate(-45deg); }
.hitmarker i:nth-child(4) { left: 4px; top: 7px; transform: rotate(45deg); }

.vitals {
  position: absolute;
  left: clamp(18px, 3vw, 44px);
  bottom: max(30px, env(safe-area-inset-bottom));
  width: 300px;
  padding: 12px 14px;
  background: linear-gradient(90deg, rgba(5, 9, 9, 0.72), rgba(5, 9, 9, 0.22) 86%, transparent);
  border-left: 1px solid rgba(196, 218, 208, 0.3);
  animation: hudSlideLeft 0.65s 0.1s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.operator-tag {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.op-sigil {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  font-family: var(--mono);
  font-size: 7px;
  color: var(--orange);
  border: 1px solid rgba(255, 139, 56, 0.45);
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
}

.operator-tag > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.operator-tag b {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.13em;
  line-height: 1;
}

.operator-tag small {
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: var(--dim-2);
}

.health-row,
.armor-row {
  margin-top: 6px;
}

.vital-label {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.14em;
  color: var(--dim);
  margin-bottom: 3px;
}

.vital-label b {
  font-size: 10px;
  font-weight: 400;
  color: var(--ink);
}

.vital-bar {
  height: 4px;
  background: rgba(255, 255, 255, 0.11);
  overflow: hidden;
  transform: skewX(-18deg);
}

.vital-bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #d5ded6, #f3f2e7);
  transition: width 0.2s ease, background 0.2s ease;
}

.vital-bar.armor i {
  background: linear-gradient(90deg, #b88c65, var(--orange-2));
  width: 100%;
}

.vitals.low .vital-bar i {
  background: var(--red);
  box-shadow: 0 0 10px rgba(255, 73, 62, 0.6);
}

.vitals-foot {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: var(--dim-2);
}

.weapon-panel {
  position: absolute;
  right: clamp(18px, 3vw, 44px);
  bottom: max(30px, env(safe-area-inset-bottom));
  width: 264px;
  padding: 11px 14px 10px;
  background: linear-gradient(270deg, rgba(5, 9, 9, 0.74), rgba(5, 9, 9, 0.18) 88%, transparent);
  border-right: 1px solid rgba(196, 218, 208, 0.3);
  text-align: right;
  animation: hudSlideRight 0.65s 0.1s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.weapon-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.14em;
  color: var(--dim);
}

.weapon-top span:first-child {
  font-family: var(--display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--ink-soft);
}

.weapon-top span:last-child {
  color: var(--orange);
}

.ammo-readout {
  display: flex;
  justify-content: flex-end;
  align-items: baseline;
  gap: 5px;
  margin-top: 2px;
  font-family: var(--display);
  font-weight: 600;
  line-height: 0.9;
  color: var(--ink);
}

#ammo-mag {
  font-size: 50px;
  letter-spacing: 0.02em;
}

.ammo-slash {
  font-size: 20px;
  color: var(--dim-2);
  font-weight: 400;
}

#ammo-reserve {
  font-size: 22px;
  color: var(--dim);
  font-weight: 500;
}

.ammo-bar {
  height: 2px;
  margin: 5px 0 7px;
  background: rgba(255, 255, 255, 0.11);
  overflow: hidden;
}

.ammo-bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--orange);
  transition: width 0.18s ease;
}

.weapon-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: var(--dim-2);
}

#reload-state {
  color: var(--dim);
}

.frag-count {
  display: flex;
  align-items: center;
  gap: 3px;
  color: var(--dim);
}

.frag-count i {
  width: 6px;
  height: 8px;
  border-radius: 2px 2px 3px 3px;
  background: var(--orange);
  opacity: 0.68;
}

.frag-count b {
  font-weight: 400;
  color: var(--orange-2);
}

.radio {
  position: absolute;
  left: 50%;
  bottom: 98px;
  transform: translateX(-50%);
  display: flex;
  align-items: stretch;
  max-width: min(560px, 72vw);
  background: rgba(4, 8, 8, 0.76);
  border: 1px solid rgba(196, 218, 208, 0.15);
  animation: radioIn 0.25s ease both;
}

@keyframes radioIn {
  from { opacity: 0; transform: translate(-50%, 6px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.radio-tag {
  display: flex;
  align-items: center;
  padding: 7px 9px;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.13em;
  color: #160a04;
  background: var(--orange);
  flex: 0 0 auto;
}

#radio-text {
  padding: 7px 12px;
  font-family: var(--mono);
  font-size: 7.5px;
  line-height: 1.5;
  letter-spacing: 0.02em;
  color: var(--ink-soft);
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 150px;
  transform: translateX(-50%) translateY(6px);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  color: var(--orange-2);
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
  text-shadow: 0 2px 8px #000;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.announce {
  position: absolute;
  left: 50%;
  top: 35%;
  transform: translate(-50%, -50%);
  text-align: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s;
  white-space: nowrap;
}

.announce.show {
  opacity: 1;
  visibility: visible;
}

.announce-kicker {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.4em;
  color: var(--orange);
  margin-bottom: 5px;
}

.announce-main {
  font-family: var(--display);
  font-size: clamp(46px, 7vw, 86px);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: 0.12em;
  text-shadow: 0 4px 26px rgba(0, 0, 0, 0.65);
}

.announce-main em {
  font-style: normal;
  color: var(--orange);
}

.announce-sub {
  margin-top: 8px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.24em;
  color: var(--dim);
}

.announce.show .announce-main {
  animation: announceIn 0.45s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes announceIn {
  from { opacity: 0; letter-spacing: 0.25em; transform: scale(1.06); }
  to { opacity: 1; letter-spacing: 0.12em; transform: scale(1); }
}

.controls-hint {
  position: absolute;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  display: flex;
  gap: 16px;
  white-space: nowrap;
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.06em;
  color: var(--dim-2);
}

.controls-hint span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.controls-hint kbd {
  height: 14px;
  min-width: 15px;
  font-size: 5.5px;
}

.mission-timer {
  position: absolute;
  left: 50%;
  top: 66px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  font-family: var(--mono);
}

#mission-time {
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--ink-soft);
}

.mission-timer small {
  font-size: 5px;
  letter-spacing: 0.18em;
  color: var(--dim-2);
}

/* ---------- touch controls ---------- */
.touch-ui {
  position: absolute;
  inset: 0;
  z-index: 60;
  pointer-events: none;
}

.touch-stick {
  position: absolute;
  left: max(24px, env(safe-area-inset-left));
  bottom: max(24px, env(safe-area-inset-bottom));
  width: 122px;
  height: 122px;
  pointer-events: auto;
  touch-action: none;
}

.stick-ring {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(225, 235, 226, 0.24);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(10, 15, 15, 0.16), rgba(10, 15, 15, 0.42));
  box-shadow: 0 0 30px rgba(0, 0, 0, 0.2) inset;
}

.stick-ring::before {
  content: '';
  position: absolute;
  inset: 18px;
  border: 1px dashed rgba(225, 235, 226, 0.08);
  border-radius: 50%;
}

.stick-knob {
  position: absolute;
  width: 46px;
  height: 46px;
  left: 38px;
  top: 38px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.38);
  background: radial-gradient(circle at 38% 34%, rgba(255, 255, 255, 0.24), rgba(255, 255, 255, 0.06));
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.3);
  transition: transform 0.06s linear;
}

.stick-cardinal {
  position: absolute;
  font-size: 6px;
  color: rgba(234, 240, 232, 0.3);
}

.stick-cardinal.n { left: 50%; top: 7px; transform: translateX(-50%); }
.stick-cardinal.e { right: 8px; top: 50%; transform: translateY(-50%); }
.stick-cardinal.s { left: 50%; bottom: 7px; transform: translateX(-50%); }
.stick-cardinal.w { left: 8px; top: 50%; transform: translateY(-50%); }

.touch-stick > span {
  position: absolute;
  left: 50%;
  bottom: -14px;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.18em;
  color: rgba(226, 236, 228, 0.32);
}

.look-hint {
  position: absolute;
  right: 30%;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.15em;
  color: rgba(230, 236, 229, 0.28);
  opacity: 1;
  transition: opacity 0.5s ease;
  text-align: center;
  line-height: 2;
}

.look-hint span {
  display: block;
  font-size: 18px;
  line-height: 1;
}

.touch-actions {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(18px, env(safe-area-inset-bottom));
  width: 200px;
  height: 190px;
  pointer-events: none;
}

.touch-btn {
  position: absolute;
  pointer-events: auto;
  touch-action: none;
  border: 1px solid rgba(228, 238, 230, 0.25);
  background: rgba(7, 12, 12, 0.35);
  backdrop-filter: blur(4px);
  border-radius: 50%;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.04em;
  color: rgba(240, 242, 235, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s, transform 0.08s;
}

.touch-btn:active,
.touch-btn.active {
  background: rgba(255, 139, 56, 0.38);
  border-color: var(--orange);
  transform: scale(0.94);
}

.touch-btn.small {
  width: 46px;
  height: 46px;
}

.touch-btn.small.jump {
  right: 2px;
  bottom: 116px;
}

#btn-aim { right: 174px; bottom: 22px; }
#btn-swap { right: 120px; bottom: 110px; }
#btn-reload { right: 52px; bottom: 118px; }
#btn-grenade { right: 154px; bottom: 92px; }

.touch-btn.fire {
  right: 2px;
  bottom: 20px;
  width: 92px;
  height: 92px;
  border-color: rgba(255, 139, 56, 0.65);
  background: radial-gradient(circle, rgba(255, 139, 56, 0.32), rgba(10, 10, 8, 0.32) 70%);
  box-shadow: 0 0 32px rgba(255, 104, 24, 0.1), 0 0 0 8px rgba(255, 139, 56, 0.045);
}

.touch-btn.fire span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
}

.touch-pause {
  position: absolute;
  left: 50%;
  top: max(9px, env(safe-area-inset-top));
  transform: translateX(-50%);
  pointer-events: auto;
}

.touch-pause button {
  width: 31px;
  height: 28px;
  border: 1px solid rgba(220, 233, 224, 0.22);
  background: rgba(5, 9, 9, 0.4);
  color: var(--dim);
  font-family: var(--mono);
  font-size: 10px;
}

.rotate-hint {
  position: absolute;
  left: 50%;
  top: 45px;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.14em;
  color: var(--orange);
  opacity: 0;
  transition: opacity 0.5s ease;
  white-space: nowrap;
}

.rotate-hint.show {
  opacity: 0.8;
}

/* ---------- overlays ---------- */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(3, 5, 5, 0.68);
  backdrop-filter: blur(11px) saturate(0.8);
  animation: overlayIn 0.25s ease both;
}

@keyframes overlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.overlay-panel {
  position: relative;
  width: min(540px, 94vw);
  padding: 34px 38px 30px;
  background: linear-gradient(150deg, rgba(17, 22, 22, 0.97), rgba(7, 10, 10, 0.97));
  border: 1px solid var(--line-strong);
  box-shadow: 0 30px 110px rgba(0, 0, 0, 0.7);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
}

.overlay-panel::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 42%;
  height: 2px;
  background: var(--orange);
  box-shadow: 0 0 18px rgba(255, 139, 56, 0.35);
}

.panel-code {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.26em;
  color: var(--orange);
  margin-bottom: 15px;
}

.overlay-panel h2 {
  margin: 0;
  font-size: clamp(38px, 5vw, 56px);
  font-weight: 600;
  line-height: 0.88;
  letter-spacing: 0.04em;
}

.overlay-panel h2 em {
  display: block;
  color: var(--orange);
  font-style: normal;
}

.panel-copy {
  margin: 14px 0 22px;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.8;
  color: var(--dim);
  max-width: 400px;
}

.pause-stats,
.end-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  margin-bottom: 22px;
}

.pause-stats > div {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 12px 0;
}

.pause-stats span,
.end-stats span {
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.16em;
  color: var(--dim-2);
}

.pause-stats b {
  font-family: var(--display);
  font-size: 25px;
  font-weight: 600;
  line-height: 1;
  color: var(--ink);
}

.panel-actions {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.panel-btn {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.025);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.16em;
  color: var(--ink-soft);
  transition: background 0.15s, border-color 0.15s;
  text-align: left;
  padding: 11px 15px;
}

.panel-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--line-strong);
}

.panel-btn.primary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--orange);
  border-color: var(--orange);
  color: #170a03;
  min-height: 58px;
  padding: 10px 16px;
}

.panel-btn.primary:hover {
  background: #ffa25e;
}

.panel-btn.primary small {
  font-size: 5.5px;
  opacity: 0.56;
  letter-spacing: 0.12em;
}

.panel-btn.danger {
  color: #ca817a;
  border-color: rgba(255, 73, 62, 0.18);
}

.panel-btn.danger:hover {
  background: rgba(255, 73, 62, 0.08);
  border-color: rgba(255, 73, 62, 0.35);
}

.pause-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 9px 15px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(200, 218, 211, 0.09);
  font-family: var(--mono);
  font-size: 5.5px;
  letter-spacing: 0.08em;
  color: var(--dim-2);
}

.pause-keys span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.end-stats {
  grid-template-columns: repeat(2, 1fr);
  margin-top: 4px;
  margin-bottom: 22px;
}

.end-stats > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px 10px 0;
  border-bottom: 1px solid rgba(200, 218, 211, 0.08);
}

.end-stats > div:nth-child(odd) {
  border-right: 1px solid rgba(200, 218, 211, 0.08);
  padding-left: 0;
}

.end-stats > div:nth-child(even) {
  padding-left: 14px;
}

.end-stats b {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  line-height: 1;
  color: var(--ink);
}

.end-stats > div:first-child b {
  color: var(--orange);
  font-size: 30px;
}

#end.dead .panel-code,
#end.dead h2 em {
  color: var(--red);
}

#end.dead .overlay-panel::before {
  background: var(--red);
  box-shadow: 0 0 18px rgba(255, 73, 62, 0.35);
}

#end.dead .panel-btn.primary {
  background: var(--red);
  border-color: var(--red);
  color: #190503;
}

.rotate-overlay {
  position: absolute;
  inset: 0;
  z-index: 400;
  background: #070a0a;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  text-align: center;
}

.rotate-overlay.hidden {
  display: none;
}

.rotate-icon {
  font-size: 44px;
  color: var(--orange);
  animation: rotatePulse 1.5s ease-in-out infinite;
}

@keyframes rotatePulse {
  50% { transform: rotate(90deg); opacity: 0.5; }
}

.rotate-overlay b {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.18em;
}

.rotate-overlay span {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.1em;
  color: var(--dim);
}

/* ---------- responsive ---------- */
@media (max-width: 1180px) {
  .menu-content {
    grid-template-columns: minmax(0, 1fr) minmax(260px, 0.42fr);
    gap: 30px;
  }

  .menu-side .controls-card {
    display: none;
  }

  .title-solid { font-size: clamp(68px, 11vw, 132px); }
  .title-ghost { font-size: clamp(52px, 8.4vw, 104px); }
}

@media (max-width: 860px) {
  .menu-content {
    display: block;
    padding-top: 18px;
  }

  .menu-side {
    display: none;
  }

  .menu-hero {
    max-width: 600px;
    margin: 0 auto;
  }

  .hero-copy {
    margin: 24px 0 19px;
  }

  .menu-top {
    padding-left: 20px;
    padding-right: 20px;
  }

  .menu-status .menu-clock,
  .menu-status > div {
    display: none;
  }

  .menu-footer {
    display: none;
  }

  .mobile-tip {
    display: block;
  }

  .mission-card {
    max-width: 560px;
  }

  .radar-panel {
    width: 142px;
  }

  .score-panel {
    top: calc(clamp(22px, 4vh, 42px) + 192px);
    gap: 10px;
  }

  .killfeed {
    display: none;
  }

  .objective-panel {
    width: 255px;
  }

  .obj-title {
    font-size: 20px;
  }

  .controls-hint {
    display: none;
  }

  .mission-timer {
    display: none;
  }

  .vitals {
    width: 245px;
  }

  .weapon-panel {
    width: 224px;
  }

  #ammo-mag {
    font-size: 42px;
  }
}

@media (max-width: 640px) {
  .menu {
    background:
      linear-gradient(90deg, rgba(5, 7, 8, 0.96) 0%, rgba(5, 7, 8, 0.82) 55%, rgba(5, 7, 8, 0.35) 100%),
