// Procedural audio engine. Everything is synthesized — no external samples.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.started = false;
    this.noise = null;
  }

  init() {
    if (this.ctx) {
      this.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.62;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.18;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);
    this.noise = this.makeNoise(2.6);
    this.startAmbience();
    this.started = true;
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.62, this.ctx.currentTime + 0.08);
    }
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.92 + white * 0.08;
      data[i] = white * 0.5 + last * 1.8;
    }
    return buffer;
  }

  startAmbience() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    // Desert wind.
    const wind = ctx.createBufferSource();
    wind.buffer = this.noise;
    wind.loop = true;
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 360;
    windFilter.Q.value = 0.6;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.028;
    wind.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(this.master);

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain);
    lfoGain.connect(windGain.gain);
    lfo.start(now);
    wind.start(now);

    // Low electrical drone.
    const drone = ctx.createOscillator();
    drone.type = 'sine';
    drone.frequency.value = 49;
    const drone2 = ctx.createOscillator();
    drone2.type = 'triangle';
    drone2.frequency.value = 73.5;
    const droneGain = ctx.createGain();
    droneGain.gain.value = 0.008;
    const drone2Gain = ctx.createGain();
    drone2Gain.gain.value = 0.0025;
    drone.connect(droneGain);
    drone2.connect(drone2Gain);
    droneGain.connect(this.master);
    drone2Gain.connect(this.master);
    drone.start(now);
    drone2.start(now);
  }

  env(node, time, peak, attack, decay, sustain = 0) {
    node.gain.cancelScheduledValues(time);
    node.gain.setValueAtTime(0.0001, time);
    node.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), time + attack);
    node.gain.exponentialRampToValueAtTime(Math.max(0.0001, sustain), time + attack + decay);
  }

  burst({ duration = 0.12, volume = 0.2, type = 'bandpass', freq = 900, q = 0.7, attack = 0.002, pan = 0, delay = 0 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.playbackRate.value = 0.9 + Math.random() * 0.25;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(60, freq * 0.35), t + duration);
    filter.Q.value = q;
    const gain = ctx.createGain();
    this.env(gain, t, volume, attack, duration, 0.0001);
    const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    src.connect(filter);
    filter.connect(gain);
    if (panner) {
      panner.pan.value = Math.max(-1, Math.min(1, pan));
      gain.connect(panner);
      panner.connect(this.master);
    } else {
      gain.connect(this.master);
    }
    src.start(t);
    src.stop(t + duration + 0.06);
  }

  tone({ freq = 440, endFreq = null, duration = 0.12, volume = 0.09, type = 'sine', pan = 0, delay = 0, attack = 0.003 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration);
    const gain = ctx.createGain();
    this.env(gain, t, volume, attack, duration, 0.0001);
    const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    osc.connect(gain);
    if (panner) {
      panner.pan.value = Math.max(-1, Math.min(1, pan));
      gain.connect(panner);
      panner.connect(this.master);
    } else {
      gain.connect(this.master);
    }
    osc.start(t);
    osc.stop(t + duration + 0.05);
  }

  shot(kind = 'rifle', pan = 0) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    if (kind === 'rifle') {
      this.burst({ duration: 0.16, volume: 0.31, freq: 1850, q: 0.7, pan });
      this.burst({ duration: 0.035, volume: 0.2, type: 'highpass', freq: 3000, pan });
      this.tone({ freq: 105, endFreq: 38, duration: 0.17, volume: 0.35, type: 'triangle', pan });
      this.tone({ freq: 68, endFreq: 32, duration: 0.22, volume: 0.24, type: 'sine', pan });
    } else if (kind === 'pistol') {
      this.burst({ duration: 0.1, volume: 0.24, freq: 2400, q: 0.9, pan });
      this.tone({ freq: 150, endFreq: 52, duration: 0.13, volume: 0.23, type: 'triangle', pan });
    } else if (kind === 'heavy') {
      this.burst({ duration: 0.22, volume: 0.4, freq: 900, q: 0.5, pan });
      this.tone({ freq: 70, endFreq: 28, duration: 0.3, volume: 0.44, type: 'sine', pan });
    } else if (kind === 'enemy') {
      this.burst({ duration: 0.12, volume: 0.12, freq: 1300, q: 0.8, pan });
      this.tone({ freq: 120, endFreq: 45, duration: 0.15, volume: 0.13, type: 'triangle', pan });
    }
    // A short tail/echo keeps the gun feeling physical.
    if (kind !== 'enemy') {
      this.burst({ duration: 0.35, volume: 0.055, type: 'lowpass', freq: 700, delay: 0.035, pan });
      this.burst({ duration: 0.5, volume: 0.028, type: 'lowpass', freq: 380, delay: 0.11, pan: -pan * 0.4 });
    }
  }

  enemyShot(distance = 20, pan = 0) {
    const near = Math.max(0.12, 1 - distance / 70);
    if (!this.ctx) return;
    this.burst({ duration: 0.13, volume: 0.16 * near, type: 'lowpass', freq: 1700, q: 0.7, pan });
    this.tone({ freq: 110, endFreq: 42, duration: 0.16, volume: 0.16 * near, type: 'triangle', pan });
  }

  explosion(pan = 0) {
    if (!this.ctx) return;
    this.burst({ duration: 1.2, volume: 0.55, type: 'lowpass', freq: 460, q: 0.5, attack: 0.005, pan });
    this.burst({ duration: 0.18, volume: 0.34, type: 'lowpass', freq: 1100, pan });
    this.tone({ freq: 62, endFreq: 21, duration: 1.1, volume: 0.48, type: 'sine', pan });
    this.tone({ freq: 110, endFreq: 34, duration: 0.55, volume: 0.26, type: 'triangle', pan });
  }

  impact(pan = 0) {
    this.burst({ duration: 0.07, volume: 0.09, type: 'highpass', freq: 2400, pan });
    this.tone({ freq: 2400, endFreq: 1200, duration: 0.05, volume: 0.025, type: 'square', pan });
  }

  hitmarker(headshot = false) {
    if (!this.ctx) return;
    if (headshot) {
      this.tone({ freq: 2350, duration: 0.045, volume: 0.06, type: 'square' });
      this.tone({ freq: 3150, duration: 0.07, volume: 0.035, type: 'sine', delay: 0.025 });
    } else {
      this.tone({ freq: 1750, duration: 0.035, volume: 0.042, type: 'square' });
    }
  }

  reload(seconds = 1.8) {
    if (!this.ctx) return;
    const taps = [0, seconds * 0.28, seconds * 0.58, seconds * 0.88];
    taps.forEach((delay, i) => {
      this.burst({ duration: 0.035, volume: i === 0 ? 0.09 : 0.065, type: 'bandpass', freq: i === 2 ? 900 : 1700, q: 1.1, delay });
      this.tone({ freq: i === 2 ? 280 : 620, duration: 0.03, volume: 0.026, type: 'square', delay });
    });
  }

  empty() {
    this.burst({ duration: 0.025, volume: 0.05, type: 'highpass', freq: 2500 });
    this.tone({ freq: 400, duration: 0.03, volume: 0.02, type: 'square' });
  }

  switchWeapon() {
    this.burst({ duration: 0.04, volume: 0.045, type: 'bandpass', freq: 1400, q: 1 });
    this.tone({ freq: 520, endFreq: 380, duration: 0.06, volume: 0.02, type: 'square' });
  }

  footstep(sprint = false) {
    this.burst({ duration: sprint ? 0.08 : 0.11, volume: sprint ? 0.048 : 0.033, type: 'lowpass', freq: sprint ? 300 : 240, q: 0.6 });
    this.tone({ freq: sprint ? 82 : 68, endFreq: 40, duration: 0.07, volume: 0.018, type: 'sine' });
  }

  playerHit() {
    if (!this.ctx) return;
    this.tone({ freq: 160, endFreq: 55, duration: 0.17, volume: 0.2, type: 'triangle' });
    this.burst({ duration: 0.18, volume: 0.1, type: 'lowpass', freq: 700 });
  }

  nearMiss(pan = 0) {
    this.burst({ duration: 0.15, volume: 0.06, type: 'bandpass', freq: 2800, q: 2, pan });
  }

  pickup(kind = 'ammo') {
    if (!this.ctx) return;
    const base = kind === 'health' ? 620 : 520;
    this.tone({ freq: base, duration: 0.07, volume: 0.05, type: 'sine' });
    this.tone({ freq: base * 1.5, duration: 0.08, volume: 0.04, type: 'sine', delay: 0.07 });
  }

  waveAlarm() {
    if (!this.ctx) return;
    this.tone({ freq: 180, endFreq: 135, duration: 0.55, volume: 0.12, type: 'sawtooth', attack: 0.04 });
    this.tone({ freq: 180, endFreq: 135, duration: 0.55, volume: 0.1, type: 'sawtooth', delay: 0.7, attack: 0.04 });
    this.burst({ duration: 0.4, volume: 0.04, type: 'lowpass', freq: 500, delay: 0.1 });
  }

  waveClear() {
    if (!this.ctx) return;
    [440, 554, 659].forEach((f, i) => {
      this.tone({ freq: f, duration: 0.35, volume: 0.045, type: 'sine', delay: i * 0.11, attack: 0.02 });
      this.tone({ freq: f * 0.5, duration: 0.35, volume: 0.022, type: 'triangle', delay: i * 0.11, attack: 0.02 });
    });
  }

  missionComplete() {
    if (!this.ctx) return;
    [392, 523, 659, 784].forEach((f, i) => {
      this.tone({ freq: f, duration: 0.75, volume: 0.055, type: 'sine', delay: i * 0.16, attack: 0.03 });
    });
    this.tone({ freq: 98, duration: 1.5, volume: 0.09, type: 'triangle', delay: 0.05, attack: 0.2 });
  }

  gameOver() {
    if (!this.ctx) return;
    this.tone({ freq: 220, endFreq: 55, duration: 1.8, volume: 0.12, type: 'sine', attack: 0.05 });
    this.burst({ duration: 1.2, volume: 0.06, type: 'lowpass', freq: 240, delay: 0.1 });
  }

  ui() {
    this.tone({ freq: 1100, endFreq: 800, duration: 0.045, volume: 0.025, type: 'square' });
  }

  radio() {
    if (!this.ctx) return;
    this.burst({ duration: 0.16, volume: 0.03, type: 'highpass', freq: 1800 });
    this.tone({ freq: 1400, duration: 0.05, volume: 0.018, type: 'square' });
  }
}

import * as THREE from '../vendor/three.module.js';

const _v = new THREE.Vector3();

class ParticleField {
  constructor(scene, max, blending, scale) {
    this.max = max;
    this.cursor = 0;
    this.positions = new Float32Array(max * 3);
    this.colors = new Float32Array(max * 3);
    this.sizes = new Float32Array(max);
    this.alphas = new Float32Array(max);
    this.vel = new Float32Array(max * 3);
    this.life = new Float32Array(max);
    this.maxLife = new Float32Array(max);
    this.gravity = new Float32Array(max);
    this.drag = new Float32Array(max);
    this.growth = new Float32Array(max);
    this.baseSize = new Float32Array(max);
    this.baseAlpha = new Float32Array(max);

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage));

    const material = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending,
      uniforms: { uScale: { value: scale } },
      vertexShader: `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        uniform float uScale;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = clamp(aSize * (uScale / max(1.0, -mv.z)), 0.0, 140.0);
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          float d = length(gl_PointCoord - 0.5) * 2.0;
          float glow = pow(max(0.0, 1.0 - d), 1.65);
          if (glow < 0.01) discard;
          gl_FragColor = vec4(vColor, vAlpha * glow);
        }
      `,
    });

    this.points = new THREE.Points(geometry, material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 8;
    scene.add(this.points);
    this.geometry = geometry;
  }

  spawn(pos, opts = {}) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % this.max;
    const i3 = i * 3;
    const color = opts.color ?? 0xffb35c;
    const c = _v.setHex(color);
    this.positions[i3] = pos.x;
    this.positions[i3 + 1] = pos.y;
    this.positions[i3 + 2] = pos.z;
    this.colors[i3] = c.x;
    this.colors[i3 + 1] = c.y;
    this.colors[i3 + 2] = c.z;
    const speed = opts.speed ?? 2;
    const spread = opts.spread ?? 1;
    const dx = (Math.random() * 2 - 1) * spread;
    const dy = (Math.random() * 2 - 1) * spread;
    const dz = (Math.random() * 2 - 1) * spread;
    const len = Math.hypot(dx, dy, dz) || 1;
    const dir = opts.dir;
    if (dir) {
      this.vel[i3] = dir.x * speed + (dx / len) * speed * 0.45;
      this.vel[i3 + 1] = dir.y * speed + (dy / len) * speed * 0.45;
      this.vel[i3 + 2] = dir.z * speed + (dz / len) * speed * 0.45;
    } else {
      this.vel[i3] = (dx / len) * speed;
      this.vel[i3 + 1] = (dy / len) * speed;
      this.vel[i3 + 2] = (dz / len) * speed;
    }
    const life = (opts.life ?? 0.6) * (0.65 + Math.random() * 0.7);
    this.life[i] = life;
    this.maxLife[i] = life;
    this.gravity[i] = opts.gravity ?? 4;
    this.drag[i] = opts.drag ?? 0.6;
    this.growth[i] = opts.growth ?? 0.4;
    this.baseSize[i] = (opts.size ?? 3) * (0.7 + Math.random() * 0.6);
    this.baseAlpha[i] = opts.alpha ?? 0.85;
    this.sizes[i] = this.baseSize[i];
    this.alphas[i] = this.baseAlpha[i];
  }

  update(dt) {
    const { positions, vel, life, maxLife, gravity, drag, sizes, alphas, baseSize, baseAlpha, growth } = this;
    for (let i = 0; i < this.max; i++) {
      if (life[i] <= 0) {
        if (alphas[i] !== 0) alphas[i] = 0;
        continue;
      }
      life[i] -= dt;
      if (life[i] <= 0) {
        alphas[i] = 0;
        continue;
      }
      const i3 = i * 3;
      const f = Math.max(0, 1 - drag[i] * dt);
      vel[i3] *= f;
      vel[i3 + 1] = vel[i3 + 1] * f - gravity[i] * dt;
      vel[i3 + 2] *= f;
      positions[i3] += vel[i3] * dt;
      positions[i3 + 1] += vel[i3 + 1] * dt;
      positions[i3 + 2] += vel[i3 + 2] * dt;
      if (positions[i3 + 1] < 0.03) {
        positions[i3 + 1] = 0.03;
        vel[i3 + 1] *= -0.18;
        vel[i3] *= 0.7;
        vel[i3 + 2] *= 0.7;
      }
      const k = life[i] / maxLife[i];
      alphas[i] = Math.pow(k, 0.7) * baseAlpha[i];
      sizes[i] = baseSize[i] * (1 + growth[i] * (1 - k));
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
  }
}

export class Effects {
  constructor(scene, quality = 'high') {
    this.scene = scene;
    this.high = quality === 'high';
    const scale = Math.min(window.innerHeight, 1200) * 0.55;
    this.sparks = new ParticleField(scene, this.high ? 900 : 420, THREE.AdditiveBlending, scale);
    this.smoke = new ParticleField(scene, this.high ? 480 : 220, THREE.NormalBlending, scale * 1.1);
    this.tracers = [];
    this.rings = [];
    this.lights = [];
    this.flashes = [];
    this.tmpColor = new THREE.Color();
  }

  muzzle(pos, dir, color = 0xffc06a, count = 5) {
    for (let i = 0; i < count; i++) {
      this.sparks.spawn(pos, {
        color: i < 2 ? 0xfff3c4 : color,
        dir,
        speed: 5 + Math.random() * 9,
        spread: 0.7,
        life: 0.09 + Math.random() * 0.08,
        size: 2.5,
        gravity: 1.5,
        drag: 3,
        growth: 0.2,
        alpha: 0.95,
      });
    }
  }

  impact(pos, color = 0xffc06a, count = 7) {
    for (let i = 0; i < count; i++) {
      this.sparks.spawn(pos, {
        color: i % 3 === 0 ? 0xfff1cc : color,
        speed: 1.5 + Math.random() * 5.5,
        spread: 1,
        life: 0.14 + Math.random() * 0.28,
        size: 1.35 + Math.random() * 1.5,
        gravity: 8,
        drag: 1.2,
        growth: 0.1,
        alpha: 0.9,
      });
      if (i < 2) {
        this.smoke.spawn(pos, {
          color: 0x77746b,
          speed: 0.3 + Math.random() * 0.8,
          spread: 1,
          life: 0.5 + Math.random() * 0.6,
          size: 5,
          gravity: -0.15,
          drag: 2.2,
          growth: 2.6,
          alpha: 0.26,
        });
      }
    }
  }

  blood(pos, dir, headshot = false) {
    for (let i = 0; i < (headshot ? 18 : 9); i++) {
      this.smoke.spawn(pos, {
        color: i % 3 === 0 ? 0x771a13 : 0x3f0a07,
        dir,
        speed: 1 + Math.random() * 3.5,
        spread: 0.75,
        life: 0.25 + Math.random() * 0.35,
        size: 2 + Math.random() * 3,
        gravity: 9,
        drag: 0.9,
        growth: 1.3,
        alpha: 0.8,
      });
    }
    this.sparks.spawn(pos, { color: 0xffcf9d, speed: 2, spread: 1, life: 0.12, size: 1.8, gravity: 5, alpha: 0.5 });
  }

  tracer(start, end, color = 0xffc170, duration = 0.075, opacity = 0.9) {
    const geo = new THREE.BufferGeometry().setFromPoints([start.clone(), end.clone()]);
    const mat = new THREE.LineBasicMaterial({
      color,
      transparent: true,
      opacity,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const line = new THREE.Line(geo, mat);
    line.frustumCulled = false;
    line.renderOrder = 7;
    this.scene.add(line);
    this.tracers.push({ line, life: duration, maxLife: duration, baseOpacity: opacity });
  }

  smokePuff(pos, color = 0x6b6a63, count = 7, force = 1.2, size = 5) {
    for (let i = 0; i < count; i++) {
      this.smoke.spawn(pos, {
        color,
        speed: (0.2 + Math.random() * force) * 1.5,
        spread: 0.8,
        life: 0.7 + Math.random() * 1.2,
        size: size * (0.6 + Math.random() * 0.8),
        gravity: -0.08,
        drag: 1.1,
        growth: 3.2,
        alpha: 0.24,
      });
    }
  }

  explosion(pos) {
    for (let i = 0; i < 42; i++) {
      this.sparks.spawn(pos, {
        color: i % 4 === 0 ? 0xfff4ca : i % 3 === 0 ? 0xff4a18 : 0xff9a2e,
        speed: 5 + Math.random() * 17,
        spread: 1,
        life: 0.25 + Math.random() * 0.65,
        size: 2 + Math.random() * 4,
        gravity: 6,
        drag: 1.3,
        growth: 0.2,
        alpha: 1,
      });
    }
    for (let i = 0; i < 24; i++) {
      this.smoke.spawn(pos, {
        color: i % 5 === 0 ? 0x24211e : 0x45413a,
        speed: 1.2 + Math.random() * 5,
        spread: 1,
        life: 1.1 + Math.random() * 1.8,
        size: 9 + Math.random() * 18,
        gravity: -0.45,
        drag: 1.2,
        growth: 3.5,
        alpha: 0.38,
      });
    }
    for (let i = 0; i < 12; i++) {
      this.smoke.spawn(pos, {
        color: 0x1b1714,
        speed: 7 + Math.random() * 13,
        spread: 1,
        life: 0.5 + Math.random() * 0.9,
        size: 3 + Math.random() * 6,
        gravity: 15,
        drag: 0.8,
        growth: 0.7,
        alpha: 0.8,
      });
    }

    const geo = new THREE.SphereGeometry(1, 16, 10);
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffb05b,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const flash = new THREE.Mesh(geo, mat);
    flash.position.copy(pos);
    flash.scale.setScalar(0.8);
    flash.renderOrder = 9;
    this.scene.add(flash);
    this.flashes.push({ mesh: flash, life: 0.28, maxLife: 0.28 });

    const ringGeo = new THREE.RingGeometry(0.5, 0.85, 40);
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffc27d,
      transparent: true,
      opacity: 0.8,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(pos.x, 0.06, pos.z);
    this.scene.add(ring);
    this.rings.push({ mesh: ring, life: 0.65, maxLife: 0.65 });

    const light = new THREE.PointLight(0xff8a35, 55, 18, 2);
    light.position.copy(pos).y += 0.6;
    this.scene.add(light);
    this.lights.push({ light, life: 0.3, maxLife: 0.3, base: 55 });
  }

  flash(pos, color = 0xffb366, intensity = 16, distance = 8) {
    const light = new THREE.PointLight(color, intensity, distance, 2);
    light.position.copy(pos);
    this.scene.add(light);
    this.lights.push({ light, life: 0.07, maxLife: 0.07, base: intensity });
  }

  update(dt) {
    this.sparks.update(dt);
    this.smoke.update(dt);
    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i];
      t.life -= dt;
      t.line.material.opacity = Math.max(0, t.life / t.maxLife) * t.baseOpacity;
      if (t.life <= 0) {
        this.scene.remove(t.line);
        t.line.geometry.dispose();
        t.line.material.dispose();
        this.tracers.splice(i, 1);
      }
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      const k = 1 - r.life / r.maxLife;
      r.mesh.scale.setScalar(1 + k * 14);
      r.mesh.material.opacity = (1 - k) * 0.8;
      if (r.life <= 0) {
        this.scene.remove(r.mesh);
        r.mesh.geometry.dispose();
        r.mesh.material.dispose();
        this.rings.splice(i, 1);
      }
    }
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.life -= dt;
      const k = 1 - f.life / f.maxLife;
      f.mesh.scale.setScalar(0.8 + k * 5.4);
      f.mesh.material.opacity = (1 - k) * 0.9;
      if (f.life <= 0) {
        this.scene.remove(f.mesh);
        f.mesh.geometry.dispose();
        f.mesh.material.dispose();
        this.flashes.splice(i, 1);
      }
    }
    for (let i = this.lights.length - 1; i >= 0; i--) {
      const l = this.lights[i];
      l.life -= dt;
      l.light.intensity = Math.max(0, l.life / l.maxLife) * l.base;
      if (l.life <= 0) {
        this.scene.remove(l.light);
        this.lights.splice(i, 1);
      }
    }
  }
}

import * as THREE from '../vendor/three.module.js';

// Deterministic RNG keeps the compound composition stable between reloads.
function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeCanvas(size, paint) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  paint(ctx, size);
  return canvas;
}

function textureFromCanvas(canvas, repeatX = 1, repeatY = 1) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeatX, repeatY);
  tex.anisotropy = 4;
  return tex;
}

function makeSandTexture(seed = 7) {
  const rnd = mulberry32(seed);
  return makeCanvas(512, (ctx, size) => {
    const img = ctx.createImageData(size, size);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const i = (y * size + x) * 4;
        const grain = (rnd() - 0.5) * 25;
        const ripple = Math.sin(x * 0.045 + Math.sin(y * 0.02) * 2.2) * 4.5;
        const band = Math.sin(y * 0.13 + x * 0.012) * 2.5;
        img.data[i] = 110 + grain + ripple + band;
        img.data[i + 1] = 101 + grain * 0.9 + ripple + band;
        img.data[i + 2] = 82 + grain * 0.75 + ripple + band;
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.globalAlpha = 0.18;
    for (let i = 0; i < 130; i++) {
      ctx.fillStyle = rnd() > 0.5 ? '#2b261e' : '#d0c1a2';
      const r = rnd() * 1.8 + 0.2;
      ctx.beginPath();
      ctx.arc(rnd() * size, rnd() * size, r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  });
}

function makeConcreteTexture(seed = 19) {
  const rnd = mulberry32(seed);
  return makeCanvas(512, (ctx, size) => {
    const img = ctx.createImageData(size, size);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const i = (y * size + x) * 4;
        const grain = (rnd() - 0.5) * 19;
        const stain = Math.sin(x * 0.02 + y * 0.008) * 3;
        img.data[i] = 95 + grain + stain;
        img.data[i + 1] = 97 + grain + stain;
        img.data[i + 2] = 91 + grain + stain;
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(35,38,35,.38)';
    for (let i = 0; i < 18; i++) {
      ctx.beginPath();
      let x = rnd() * size;
      let y = rnd() * size;
      ctx.moveTo(x, y);
      for (let j = 0; j < 5; j++) {
        x += (rnd() - 0.5) * 34;
        y += rnd() * 18;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(30,32,30,.18)';
    for (let i = 0; i < 28; i++) {
      ctx.beginPath();
      ctx.ellipse(rnd() * size, rnd() * size, 2 + rnd() * 15, 1 + rnd() * 6, rnd() * 3, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

function makeMetalTexture(seed = 31) {
  const rnd = mulberry32(seed);
  return makeCanvas(512, (ctx, size) => {
    const img = ctx.createImageData(size, size);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const i = (y * size + x) * 4;
        const grain = (rnd() - 0.5) * 15;
        const scratch = Math.sin(x * 0.7 + y * 0.05) > 0.94 ? 11 : 0;
        img.data[i] = 72 + grain + scratch;
        img.data[i + 1] = 82 + grain + scratch;
        img.data[i + 2] = 79 + grain + scratch;
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.globalAlpha = 0.25;
    for (let i = 0; i < 34; i++) {
      ctx.fillStyle = rnd() > 0.4 ? '#241f1a' : '#b09a78';
      ctx.fillRect(rnd() * size, rnd() * size, 1 + rnd() * 3, 6 + rnd() * 90);
    }
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 60; i++) {
      ctx.fillStyle = '#090d0d';
      ctx.beginPath();
      ctx.arc(rnd() * size, rnd() * size, 1.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  });
}

function makeContainerTexture(seed = 41) {
  const rnd = mulberry32(seed);
  return makeCanvas(512, (ctx, size) => {
    const img = ctx.createImageData(size, size);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const i = (y * size + x) * 4;
        const rib = Math.sin(x * Math.PI / 13);
        const shade = rib > 0.55 ? 18 : rib < -0.6 ? -13 : 0;
        const grain = (rnd() - 0.5) * 13;
        img.data[i] = 84 + shade + grain;
        img.data[i + 1] = 101 + shade + grain;
        img.data[i + 2] = 98 + shade + grain;
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.globalAlpha = 0.3;
    for (let i = 0; i < 35; i++) {
      ctx.fillStyle = rnd() > 0.45 ? '#6d3c22' : '#1c2322';
      const x = rnd() * size;
      const y = rnd() * size;
      ctx.fillRect(x, y, 1 + rnd() * 2, 4 + rnd() * 100);
    }
    ctx.globalAlpha = 0.45;
    ctx.strokeStyle = '#222b29';
    ctx.lineWidth = 2;
    ctx.strokeRect(2, 2, size - 4, size - 4);
    ctx.globalAlpha = 1;
  });
}

function makeWoodTexture(seed = 53) {
  const rnd = mulberry32(seed);
  return makeCanvas(512, (ctx, size) => {
    ctx.fillStyle = '#715136';
    ctx.fillRect(0, 0, size, size);
    const planks = 6;
    for (let p = 0; p < planks; p++) {
      const y = (p / planks) * size;
      const shade = 68 + rnd() * 25;
      ctx.fillStyle = `rgb(${shade + 24},${shade},${shade - 20})`;
      ctx.fillRect(0, y + 1, size, size / planks - 2);
      ctx.strokeStyle = 'rgba(38,25,16,.55)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(size, y);
      ctx.stroke();
      for (let j = 0; j < 14; j++) {
        ctx.strokeStyle = `rgba(50,32,18,${0.1 + rnd() * 0.15})`;
        ctx.beginPath();
        const yy = y + 3 + rnd() * (size / planks - 6);
        ctx.moveTo(0, yy);
        ctx.bezierCurveTo(size * 0.3, yy + rnd() * 4, size * 0.6, yy - rnd() * 4, size, yy + rnd() * 2);
        ctx.stroke();
      }
    }
    ctx.fillStyle = 'rgba(20,12,7,.35)';
    for (let i = 0; i < 14; i++) {
      ctx.beginPath();
      ctx.arc(rnd() * size, rnd() * size, 2 + rnd() * 6, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

function makeSandbagTexture(seed = 67) {
  const rnd = mulberry32(seed);
  return makeCanvas(256, (ctx, size) => {
    const img = ctx.createImageData(size, size);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const i = (y * size + x) * 4;
        const weave = (Math.sin(x * 1.7) + Math.sin(y * 1.7)) * 4;
        const grain = (rnd() - 0.5) * 18;
        img.data[i] = 106 + grain + weave;
        img.data[i + 1] = 93 + grain + weave;
        img.data[i + 2] = 70 + grain + weave;
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.strokeStyle = 'rgba(46,36,23,.3)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 40; i++) {
      ctx.beginPath();
      ctx.moveTo(rnd() * size, rnd() * size);
      ctx.lineTo(rnd() * size, rnd() * size);
      ctx.stroke();
    }
  });
}

function makeGroundDecal() {
  return makeCanvas(1024, (ctx, size) => {
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.strokeStyle = 'rgba(213,209,178,.3)';
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.arc(0, 0, 288, 0, Math.PI * 2);
    ctx.stroke();
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, 263, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, 340, -0.2, 0.75);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, 340, 2.95, 3.9);
    ctx.stroke();
    ctx.rotate(-0.16);
    ctx.fillStyle = 'rgba(219,212,174,.4)';
    ctx.font = '700 176px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('07', -34, -74);
    ctx.font = '600 35px "Barlow Condensed", sans-serif';
    ctx.letterSpacing = '13px';
    ctx.fillText('BLACKSITE', 0, 84);
    ctx.font = '400 18px monospace';
    ctx.letterSpacing = '5px';
    ctx.fillStyle = 'rgba(219,212,174,.25)';
    ctx.fillText('LZ // DO NOT BLOCK', 0, 124);
    ctx.restore();

    // Worn paint / oil marks.
    ctx.globalAlpha = 0.23;
    for (let i = 0; i < 24; i++) {
      const x = 100 + Math.random() * 824;
      const y = 100 + Math.random() * 824;
      const r = 18 + Math.random() * 65;
      const grd = ctx.createRadialGradient(x, y, 1, x, y, r);
      grd.addColorStop(0, 'rgba(18,17,13,.8)');
      grd.addColorStop(1, 'rgba(18,17,13,0)');
      ctx.fillStyle = grd;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 0.2;
    ctx.fillStyle = '#d2b05d';
    for (let i = 0; i < 14; i++) {
      const x = 0;
      const y = 140 + i * 23;
      ctx.save();
      ctx.translate(55, y);
      ctx.rotate(-0.25);
      ctx.fillRect(0, 0, 84, 8);
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  });
}

function makeGlowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  return textureFromCanvas(makeCanvas(128, (ctx, size) => {
    const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
    g.addColorStop(0, inner);
    g.addColorStop(0.2, 'rgba(255,255,255,.75)');
    g.addColorStop(0.68, 'rgba(255,255,255,.18)');
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);
  }));
}

function makeHazardTexture() {
  return makeCanvas(256, (ctx, size) => {
    ctx.fillStyle = '#b4923d';
    ctx.fillRect(0, 0, size, size);
    ctx.strokeStyle = '#151612';
    ctx.lineWidth = 38;
    for (let i = -size; i < size * 2; i += 76) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i + size, size);
      ctx.stroke();
    }
    ctx.globalAlpha = 0.2;
    ctx.fillStyle = '#000';
    for (let i = 0; i < 90; i++) ctx.fillRect(Math.random() * size, Math.random() * size, 2 + Math.random() * 14, 1 + Math.random() * 2);
    ctx.globalAlpha = 1;
  });
}

function makeSignTexture(text, sub = '') {
  return textureFromCanvas(makeCanvas(512, (ctx, size) => {
    ctx.clearRect(0, 0, size, size);
    ctx.fillStyle = 'rgba(10,13,12,.75)';
    ctx.fillRect(0, 156, size, 200);
    ctx.strokeStyle = 'rgba(255,139,56,.55)';
    ctx.lineWidth = 3;
    ctx.strokeRect(4, 160, size - 8, 192);
    ctx.fillStyle = 'rgba(238,236,221,.88)';
    ctx.font = '700 82px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, size / 2, 235);
    if (sub) {
      ctx.fillStyle = 'rgba(255,139,56,.8)';
      ctx.font = '400 19px monospace';
      ctx.letterSpacing = '8px';
      ctx.fillText(sub, size / 2, 308);
    }
  }), 1, 1);
}

export function createWorld(scene, renderer, quality = 'high') {
  const high = quality === 'high';
  const rnd = mulberry32(7741);
  const colliders = [];
  const mapWalls = [];
  const animated = [];
  const fires = [];
  const dustLights = [];
  const spawnPoints = [];
  const tmpBox = new THREE.Box3();
  const tmpVec = new THREE.Vector3();
  const dummy = new THREE.Object3D();

  scene.background = new THREE.Color(0x06090b);
  scene.fog = new THREE.FogExp2(0x0a1112, high ? 0.0095 : 0.0115);

  // ----- textures -----
  const sandTex = makeSandTexture();
  const concreteTex = makeConcreteTexture();
  const metalTex = makeMetalTexture();
  const containerTex = makeContainerTexture();
  const woodTex = makeWoodTexture();
  const sandbagTex = makeSandbagTexture();
  const hazardTex = makeHazardTexture();

  const groundTex = sandTex.clone();
  groundTex.needsUpdate = true;
  groundTex.repeat.set(20, 20);

  const concreteGroundTex = concreteTex.clone();
  concreteGroundTex.needsUpdate = true;
  concreteGroundTex.repeat.set(12, 12);

  const mats = {
    ground: new THREE.MeshStandardMaterial({ map: groundTex, color: 0xaea184, roughness: 1, metalness: 0 }),
    concrete: new THREE.MeshStandardMaterial({ map: concreteTex, color: 0xa5a69a, roughness: 0.94, metalness: 0.03 }),
    concreteDark: new THREE.MeshStandardMaterial({ map: concreteTex, color: 0x6e7269, roughness: 0.95, metalness: 0.04 }),
    concretePad: new THREE.MeshStandardMaterial({ map: concreteGroundTex, color: 0x85877c, roughness: 0.96, metalness: 0.02 }),
    metal: new THREE.MeshStandardMaterial({ map: metalTex, color: 0x88908a, roughness: 0.58, metalness: 0.5 }),
    metalDark: new THREE.MeshStandardMaterial({ map: metalTex, color: 0x4c5653, roughness: 0.62, metalness: 0.62 }),
    containerGreen: new THREE.MeshStandardMaterial({ map: containerTex, color: 0x527b6d, roughness: 0.72, metalness: 0.34 }),
    containerRust: new THREE.MeshStandardMaterial({ map: containerTex, color: 0x946047, roughness: 0.8, metalness: 0.25 }),
    containerBlue: new THREE.MeshStandardMaterial({ map: containerTex, color: 0x4e697e, roughness: 0.72, metalness: 0.32 }),
    wood: new THREE.MeshStandardMaterial({ map: woodTex, color: 0xb89269, roughness: 0.92 }),
    sandbag: new THREE.MeshStandardMaterial({ map: sandbagTex, color: 0xa89470, roughness: 1 }),
    dark: new THREE.MeshStandardMaterial({ color: 0x1e2524, roughness: 0.8, metalness: 0.25 }),
    black: new THREE.MeshStandardMaterial({ color: 0x0d1111, roughness: 0.55, metalness: 0.4 }),
    rust: new THREE.MeshStandardMaterial({ color: 0x6f3f2b, roughness: 0.9 }),
    hazard: new THREE.MeshStandardMaterial({ map: hazardTex, color: 0xffffff, roughness: 0.9 }),
    glass: new THREE.MeshStandardMaterial({ color: 0x1a3434, roughness: 0.18, metalness: 0.2, emissive: 0x1a5551, emissiveIntensity: 0.25 }),
    lightPanel: new THREE.MeshBasicMaterial({ color: 0xc4e3d8 }),
    redPanel: new THREE.MeshBasicMaterial({ color: 0xff4a2d }),
    orangePanel: new THREE.MeshBasicMaterial({ color: 0xffa14e }),
    cable: new THREE.MeshStandardMaterial({ color: 0x111514, roughness: 0.85 }),
  };
  mats.hazard.map.repeat.set(2, 1);

  // ----- sky / horizon -----
  const skyGeo = new THREE.SphereGeometry(280, 32, 20);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(0x020507) },
      mid: { value: new THREE.Color(0x0a1418) },
      bottom: { value: new THREE.Color(0x2b2c25) },
    },
    vertexShader: `
      varying vec3 vPos;
      void main() {
        vPos = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vPos;
      uniform vec3 top;
      uniform vec3 mid;
      uniform vec3 bottom;
      void main() {
        float h = clamp(vPos.y * 0.5 + 0.5, 0.0, 1.0);
        vec3 c = mix(bottom, mid, smoothstep(0.42, 0.62, h));
        c = mix(c, top, smoothstep(0.61, 0.93, h));
        gl_FragColor = vec4(c, 1.0);
      }
    `,
  });
  scene.add(new THREE.Mesh(skyGeo, skyMat));

  const starCount = high ? 800 : 420;
  const starPos = new Float32Array(starCount * 3);
  for (let i = 0; i < starCount; i++) {
    const az = rnd() * Math.PI * 2;
    const el = 0.1 + rnd() * 0.88;
    const r = 260;
    starPos[i * 3] = Math.cos(az) * Math.cos(el) * r;
    starPos[i * 3 + 1] = Math.sin(el) * r;
    starPos[i * 3 + 2] = Math.sin(az) * Math.cos(el) * r;
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
  const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
    color: 0xa8c1c2,
    size: 1.3,
    sizeAttenuation: false,
    transparent: true,
    opacity: 0.58,
    depthWrite: false,
    fog: false,
  }));
  scene.add(stars);

  const glowTex = makeGlowTexture();
  const moon = new THREE.Mesh(
    new THREE.CircleGeometry(8.5, 40),
    new THREE.MeshBasicMaterial({ color: 0xdde7df, fog: false, transparent: true, opacity: 0.92 })
  );
  moon.position.set(-120, 102, -205);
  moon.lookAt(0, 0, 0);
  scene.add(moon);
  const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex,
    color: 0xbbd7d7,
    transparent: true,
    opacity: 0.28,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    fog: false,
  }));
  moonGlow.position.copy(moon.position);
  moonGlow.scale.set(78, 78, 1);
  scene.add(moonGlow);

  function createHorizon(radius, color, base, variance, phase) {
    const segments = 128;
    const pos = [];
    const idx = [];
    for (let i = 0; i <= segments; i++) {
      const a = (i / segments) * Math.PI * 2;
      const n = Math.sin(a * 3 + phase) * 0.32 + Math.sin(a * 7.7 + phase * 1.7) * 0.18 + Math.sin(a * 13.1) * 0.08;
      const h = base + n * variance + Math.max(0, Math.sin(a * 4.3 + phase)) * variance * 0.55;
      pos.push(Math.cos(a) * radius, -3, Math.sin(a) * radius);
      pos.push(Math.cos(a) * radius, h, Math.sin(a) * radius);
      if (i < segments) {
        const k = i * 2;
        idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setIndex(idx);
    const m = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, fog: false });
    const mesh = new THREE.Mesh(g, m);
    scene.add(mesh);
  }
  createHorizon(230, 0x070d0f, 9, 22, 1.4);
  createHorizon(192, 0x0b1516, 5, 14, 4.2);

  // ----- lighting -----
  const hemi = new THREE.HemisphereLight(0x86a9aa, 0x241d14, 0.9);
  scene.add(hemi);
  const ambient = new THREE.AmbientLight(0x4b5c5d, 0.44);
  scene.add(ambient);

  const moonLight = new THREE.DirectionalLight(0xb8d2dd, 2.2);
  moonLight.position.set(-82, 102, -94);
  moonLight.castShadow = true;
  const shadowSize = high ? 2048 : 1024;
  moonLight.shadow.mapSize.set(shadowSize, shadowSize);
  moonLight.shadow.camera.near = 1;
  moonLight.shadow.camera.far = 180;
  moonLight.shadow.camera.left = -55;
  moonLight.shadow.camera.right = 55;
  moonLight.shadow.camera.top = 55;
  moonLight.shadow.camera.bottom = -55;
  moonLight.shadow.bias = -0.00045;
  moonLight.shadow.normalBias = 0.025;
  scene.add(moonLight);
  scene.add(moonLight.target);

  // ----- ground -----
  const groundGeo = new THREE.PlaneGeometry(240, 240, 80, 80);
  const posAttr = groundGeo.attributes.position;
  for (let i = 0; i < posAttr.count; i++) {
    const x = posAttr.getX(i);
    const y = posAttr.getY(i);
    const dist = Math.hypot(x, y);
    const edge = Math.max(0, (dist - 48) / 30);
    const h = Math.sin(x * 0.11 + y * 0.07) * 0.16 * edge + Math.sin(x * 0.033 - y * 0.05) * 0.4 * edge;
    posAttr.setZ(i, h);
  }
  groundGeo.computeVertexNormals();
  const ground = new THREE.Mesh(groundGeo, mats.ground);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  const pad = new THREE.Mesh(new THREE.BoxGeometry(72, 0.16, 72), mats.concretePad);
  pad.position.y = -0.02;
  pad.receiveShadow = true;
  scene.add(pad);

  const decalMat = new THREE.MeshStandardMaterial({
    map: textureFromCanvas(makeGroundDecal()),
    transparent: true,
    roughness: 0.98,
    metalness: 0,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: -2,
  });
  const decal = new THREE.Mesh(new THREE.PlaneGeometry(52, 52), decalMat);
  decal.rotation.x = -Math.PI / 2;
  decal.position.y = 0.072;
  decal.receiveShadow = true;
  scene.add(decal);

  // Faint, larger markings to break up the apron.
  const arrowTex = textureFromCanvas(makeCanvas(512, (ctx, s) => {
    ctx.clearRect(0, 0, s, s);
    ctx.save();
    ctx.translate(s / 2, s / 2);
    ctx.fillStyle = 'rgba(205,199,166,.18)';
    ctx.beginPath();
    ctx.moveTo(-40, -170);
    ctx.lineTo(100, -170);
    ctx.lineTo(100, -70);
    ctx.lineTo(170, -70);
    ctx.lineTo(0, 120);
    ctx.lineTo(-170, -70);
    ctx.lineTo(-100, -70);
    ctx.lineTo(-100, -170);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }));
  const arrow = new THREE.Mesh(new THREE.PlaneGeometry(7, 15), new THREE.MeshStandardMaterial({
    map: arrowTex,
    transparent: true,
    roughness: 1,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: -2,
  }));
  arrow.rotation.x = -Math.PI / 2;
  arrow.rotation.z = -0.36;
  arrow.position.set(12, 0.075, -5);
  scene.add(arrow);

  // ----- helpers -----
  function addCollider(cx, cz, w, d, minY, maxY, tag = 'solid') {
    colliders.push({
      box: new THREE.Box3(
        new THREE.Vector3(cx - w / 2, minY, cz - d / 2),
        new THREE.Vector3(cx + w / 2, maxY, cz + d / 2)
      ),
      tag,
    });
  }

  function addBox(x, bottom, z, w, h, d, material, opts = {}) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
    const rot = opts.rotY || 0;
    mesh.position.set(x, bottom + h / 2, z);
    mesh.rotation.y = rot;
    mesh.castShadow = opts.castShadow ?? true;
    mesh.receiveShadow = opts.receiveShadow ?? true;
    (opts.parent || scene).add(mesh);
    if (opts.collide !== false) {
      const cw = Math.abs(Math.cos(rot)) * w + Math.abs(Math.sin(rot)) * d;
      const cd = Math.abs(Math.sin(rot)) * w + Math.abs(Math.cos(rot)) * d;
      addCollider(x, z, cw, cd, bottom, bottom + h, opts.tag || 'solid');
      if (opts.map && Math.max(cw, cd) > 1.6) {
        mapWalls.push({ x, z, w: cw, d: cd, kind: opts.mapKind || 'structure' });
      }
    }
    return mesh;
  }

  function addPlaneSign(x, y, z, w, h, rotY, text, sub = '') {
    const tex = makeSignTexture(text, sub);
    const mat = new THREE.MeshStandardMaterial({
      map: tex,
      transparent: true,
      roughness: 0.7,
      emissive: 0x3a2a16,
      emissiveIntensity: 0.4,
      side: THREE.DoubleSide,
    });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
    mesh.position.set(x, y, z);
    mesh.rotation.y = rotY;
    scene.add(mesh);
    return mesh;
  }

  function addLightPanel(x, y, z, w, h, colorMat, rotY = 0) {
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(w, h), colorMat);
    panel.position.set(x, y, z);
    panel.rotation.y = rotY;
    scene.add(panel);
    return panel;
  }

  function addCrate(x, z, s = 1.15, rot = 0, bottom = 0, dark = false) {
    const mesh = addBox(x, bottom, z, s, s * 0.86, s * 0.92, dark ? mats.metalDark : mats.wood, { rotY: rot, map: true, mapKind: 'crate' });
    const edges = new THREE.LineSegments(
      new THREE.EdgesGeometry(mesh.geometry, 20),
      new THREE.LineBasicMaterial({ color: 0x251b12, transparent: true, opacity: 0.55 })
    );
    mesh.add(edges);
    const band = new THREE.Mesh(new THREE.BoxGeometry(s * 1.01, 0.055, s * 0.93), mats.metalDark);
    band.position.y = 0.08;
    mesh.add(band);
    const band2 = band.clone();
    band2.position.y = -s * 0.34;
    mesh.add(band2);
    return mesh;
  }

  function addBarrel(x, z, opts = {}) {
    const h = 1.02;
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.37, h, 14), opts.fire ? mats.rust : mats.metal);
    barrel.position.set(x, h / 2, z);
    barrel.castShadow = true;
    barrel.receiveShadow = true;
    scene.add(barrel);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.355, 0.025, 5, 14), mats.metalDark);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.26;
    barrel.add(ring);
    const ring2 = ring.clone();
    ring2.position.y = -0.26;
    barrel.add(ring2);
    addCollider(x, z, 0.72, 0.72, 0, h, 'barrel');
    if (opts.fire) {
      const light = new THREE.PointLight(0xff7b2c, 8, 9, 2);
      light.position.set(x, 1.2, z);
      scene.add(light);
      const sprites = [];
      for (let i = 0; i < 3; i++) {
        const sp = new THREE.Sprite(new THREE.SpriteMaterial({
          map: glowTex,
          color: i === 0 ? 0xff7a28 : i === 1 ? 0xffb14d : 0xff4e1a,
          transparent: true,
          opacity: i === 0 ? 0.75 : 0.45,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }));
        sp.position.set(x + (i - 1) * 0.1, 1.25 + i * 0.12, z + (i % 2 ? 0.08 : -0.06));
        sp.scale.setScalar(1.2 - i * 0.22);
        scene.add(sp);
        sprites.push(sp);
      }
      fires.push({ x, z, light, sprites, phase: rnd() * 10 });
    }
    return barrel;
  }

  function addJersey(x, z, rot, length = 2.4) {
    addBox(x, 0, z, length, 0.28, 0.75, mats.concreteDark, { rotY: rot, map: true, mapKind: 'cover' });
    const top = addBox(x, 0.28, z, length, 0.72, 0.42, mats.concrete, { rotY: rot });
    top.receiveShadow = true;
    const strip = new THREE.Mesh(new THREE.PlaneGeometry(length * 0.88, 0.18), mats.hazard);
    strip.position.set(0, 0.35, 0.216);
    top.add(strip);
    const strip2 = strip.clone();
    strip2.rotation.y = Math.PI;
    strip2.position.z = -0.216;
    top.add(strip2);
    return top;
  }

  function addContainer(x, z, rot, kind = 0) {
    const mat = kind === 0 ? mats.containerGreen : kind === 1 ? mats.containerRust : mats.containerBlue;
    const w = 6.2;
    const h = 2.62;
    const d = 2.7;
    const box = addBox(x, 0, z, w, h, d, mat, { rotY: rot, map: true, mapKind: 'container' });
    // structural rails
    const railGeo = new THREE.BoxGeometry(w + 0.1, 0.14, 0.16);
    const railMat = mats.metalDark;
    const rail1 = new THREE.Mesh(railGeo, railMat);
    rail1.position.set(0, h / 2 - 0.07, d / 2 + 0.05);
    box.add(rail1);
    const rail2 = rail1.clone();
    rail2.position.z = -d / 2 - 0.05;
    box.add(rail2);
    const end1 = new THREE.Mesh(new THREE.BoxGeometry(0.14, h, d + 0.1), railMat);
    end1.position.x = -w / 2 - 0.02;
    box.add(end1);
    const end2 = end1.clone();
    end2.position.x = w / 2 + 0.02;
    box.add(end2);
    // door seam
    const seam = new THREE.Mesh(new THREE.BoxGeometry(0.05, h * 0.78, 0.03), mats.black);
    seam.position.set(0, 0, d / 2 + 0.052);
    box.add(seam);
    return box;
  }

  function addFloodlight(x, z, targetX, targetZ, height = 6.2) {
    addBox(x, 0, z, 0.18, height, 0.18, mats.metalDark, { collide: false, castShadow: false });
    addBox(x, 0, z, 0.7, 0.16, 0.7, mats.metalDark, { collide: false, castShadow: false });
    const head = addBox(x, height - 0.35, z, 0.7, 0.42, 0.44, mats.metalDark, { collide: false, castShadow: false, rotY: Math.atan2(targetX - x, targetZ - z) });
    const lens = new THREE.Mesh(new THREE.PlaneGeometry(0.55, 0.28), mats.lightPanel);
    lens.position.set(0, -0.02, 0.23);
    head.add(lens);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex,
      color: 0xffb567,
      transparent: true,
      opacity: 0.52,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }));
    glow.position.set(x, height - 0.3, z);
    glow.scale.set(3.6, 3.6, 1);
    scene.add(glow);
    const target = new THREE.Object3D();
    target.position.set(targetX, 0.5, targetZ);
    scene.add(target);
    const spot = new THREE.SpotLight(0xffb46a, high ? 560 : 360, 42, 0.48, 0.76, 1.8);
    spot.position.set(x, height - 0.25, z);
    spot.target = target;
    scene.add(spot);
    // Volumetric-looking cone.
    const coneGeo = new THREE.ConeGeometry(5.2, height, 24, 1, true);
    const coneMat = new THREE.MeshBasicMaterial({
      color: 0xffa557,
      transparent: true,
      opacity: 0.026,
      side: THREE.DoubleSide,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const cone = new THREE.Mesh(coneGeo, coneMat);
    cone.position.set(x, height / 2, z);
    cone.rotation.z = Math.PI;
    scene.add(cone);
    return spot;
  }

  function addWatchtower(x, z) {
    const legMat = mats.metalDark;
    for (const dx of [-1.4, 1.4]) {
      for (const dz of [-1.4, 1.4]) {
        addBox(x + dx, 0, z + dz, 0.16, 5.2, 0.16, legMat, { collide: false, castShadow: true });
      }
    }
    addBox(x, 5.0, z, 3.7, 0.3, 3.7, mats.metalDark, { map: true, mapKind: 'tower' });
    for (const dx of [-1.75, 1.75]) {
      addBox(x + dx, 5.3, z, 0.09, 0.95, 3.7, mats.metalDark, { collide: false, castShadow: false });
    }
    addBox(x, 5.3, z - 1.75, 3.7, 0.95, 0.09, mats.metalDark, { collide: false, castShadow: false });
    addBox(x, 6.3, z, 4.0, 0.18, 4.0, mats.metalDark, { collide: false });
    const lamp = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 0.35), mats.lightPanel);
    lamp.position.set(x, 6.0, z - 1.83);
    lamp.rotation.y = Math.PI;
    scene.add(lamp);
    const spot = new THREE.SpotLight(0xffcf8b, high ? 330 : 220, 38, 0.5, 0.8, 2);
    spot.position.set(x, 5.95, z - 1.9);
    const t = new THREE.Object3D();
    t.position.set(x * 0.45, 0, z * 0.45);
    scene.add(t);
    spot.target = t;
    scene.add(spot);
  }

  // ----- perimeter -----
  const wallMat = mats.concreteDark;
  addBox(0, 0, -43.2, 88, 4.0, 1.1, wallMat, { map: true, mapKind: 'wall' });
  addBox(0, 0, 43.2, 88, 4.0, 1.1, wallMat, { map: true, mapKind: 'wall' });
  addBox(-43.2, 0, 0, 1.1, 4.0, 86, wallMat, { map: true, mapKind: 'wall' });
  addBox(43.2, 0, 0, 1.1, 4.0, 86, wallMat, { map: true, mapKind: 'wall' });
  // Wall buttresses give the perimeter silhouette variation.
  for (let i = -3; i <= 3; i++) {
    addBox(i * 12, 0, -42.55, 1.5, 4.5, 0.8, mats.concrete, { collide: false, castShadow: false });
    addBox(i * 12, 0, 42.55, 1.5, 4.5, 0.8, mats.concrete, { collide: false, castShadow: false });
    addBox(-42.55, 0, i * 12, 0.8, 4.5, 1.5, mats.concrete, { collide: false, castShadow: false });
    addBox(42.55, 0, i * 12, 0.8, 4.5, 1.5, mats.concrete, { collide: false, castShadow: false });
  }
  // Top edge / wire line.
  for (const side of [-1, 1]) {
    const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 87, 4), mats.cable);
    wire.rotation.z = Math.PI / 2;
    wire.position.set(0, 4.55, side * 43.2);
    scene.add(wire);
    const wire2 = wire.clone();
    wire2.rotation.set(0, 0, 0);
    wire2.rotation.x = Math.PI / 2;
    wire2.position.set(side * 43.2, 4.55, 0);
    scene.add(wire2);
  }
  // South gate visual.
  addBox(0, 0, 43.15, 10, 4.6, 1.3, mats.metalDark, { collide: true, map: true, mapKind: 'gate' });
  addBox(-5.2, 0, 42.4, 0.5, 4.8, 0.6, mats.metal, { collide: false });
  addBox(5.2, 0, 42.4, 0.5, 4.8, 0.6, mats.metal, { collide: false });
  addPlaneSign(0, 2.9, 42.45, 6.0, 1.5, 0, 'BLACKSITE 07', 'AUTHORIZED PERSONNEL ONLY');

  // ----- command building -----
  {
    const bx = -18;
    const bz = -15;
    // floor and roof
    addBox(bx, 0, bz, 16, 0.18, 10, mats.concrete, { collide: false });
