function makeMaterials() {
  return {
    gunmetal: new THREE.MeshStandardMaterial({ color: 0x59615e, roughness: 0.34, metalness: 0.72 }),
    dark: new THREE.MeshStandardMaterial({ color: 0x1c2322, roughness: 0.54, metalness: 0.42 }),
    polymer: new THREE.MeshStandardMaterial({ color: 0x2e3733, roughness: 0.78, metalness: 0.12 }),
    tan: new THREE.MeshStandardMaterial({ color: 0x72614a, roughness: 0.82, metalness: 0.06 }),
    rubber: new THREE.MeshStandardMaterial({ color: 0x141817, roughness: 0.94, metalness: 0.02 }),
    glove: new THREE.MeshStandardMaterial({ color: 0x352f27, roughness: 0.96, metalness: 0.02 }),
    sleeve: new THREE.MeshStandardMaterial({ color: 0x3f4a42, roughness: 0.96, metalness: 0.04 }),
    accent: new THREE.MeshStandardMaterial({ color: 0x6b3a1f, roughness: 0.65, metalness: 0.2 }),
    dot: new THREE.MeshBasicMaterial({ color: 0xff6b3a, toneMapped: false }),
    glass: new THREE.MeshStandardMaterial({
      color: 0x17322e,
      emissive: 0x245c50,
      emissiveIntensity: 0.8,
      roughness: 0.18,
      metalness: 0.4,
      transparent: true,
      opacity: 0.9,
    }),
  };
}

function addPart(parent, w, h, d, mat, x, y, z, rx = 0, ry = 0, rz = 0) {
  const mesh = new THREE.Mesh(UNIT_BOX, mat);
  mesh.scale.set(w, h, d);
  mesh.position.set(x, y, z);
  mesh.rotation.set(rx, ry, rz);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  parent.add(mesh);
  return mesh;
}

function addCylinder(parent, radius, length, mat, x, y, z, rx = Math.PI / 2) {
  const mesh = new THREE.Mesh(UNIT_CYL, mat);
  mesh.scale.set(radius, length, radius);
  mesh.position.set(x, y, z);
  mesh.rotation.x = rx;
  mesh.castShadow = false;
  parent.add(mesh);
  return mesh;
}

function addGlowSprite(world, parent, scale, color = 0xffc36b) {
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: world.textures.glowTex,
    color,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  }));
  sprite.scale.setScalar(scale);
  sprite.visible = false;
  parent.add(sprite);
  return sprite;
}

function finishWeapon(group, world, muzzlePos, flashScale) {
  const muzzle = new THREE.Object3D();
  muzzle.position.copy(muzzlePos);
  group.add(muzzle);
  const flash = addGlowSprite(world, group, flashScale);
  flash.position.copy(muzzlePos);
  const light = new THREE.PointLight(0xffb15c, 0, 4.5, 2);
  light.position.copy(muzzlePos);
  group.add(light);
  group.userData.muzzle = muzzle;
  group.userData.flash = flash;
  group.userData.light = light;
}

