  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  const p = await ctx.newPage();
  await p.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await p.waitForTimeout(5000);
  const info = await p.evaluate(() => ({ coarse: matchMedia('(pointer: coarse)').matches, touch: navigator.maxTouchPoints, inner: [innerWidth, innerHeight], menu: !document.getElementById('menu').classList.contains('hidden'), isTouch: window.__BLACKSITE__?.isTouch, quality: window.__BLACKSITE__?.quality }));
  await p.screenshot({ path: '/tmp/opencode/mobile-menu-real.png' });
  return info;
}
